declare(strict_types=1);require __DIR__.'/../private/form-utils.php';require __DIR__.'/../private/site.php';$errors=[];$success=false;if($_SERVER['REQUEST_METHOD']==='POST'){if(evosys_honeypot()){header('Location: ./?sent=1');exit;}if(evosys_too_fast())$errors[]='Please wait a moment and submit again.';$name=evosys_clean((string)($_POST['name']??''),120);$company=evosys_clean((string)($_POST['company']??''),160);$email=evosys_clean((string)($_POST['email']??''),180);$topic=evosys_clean((string)($_POST['topic']??''),80);$message=evosys_clean((string)($_POST['message']??''),4000);if($name==='')$errors[]='Name is required.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='A valid email is required.';if($message==='')$errors[]='Please tell us how we can help.';if(!$errors){$payload=['submitted_at'=>gmdate('c'),'name'=>$name,'company'=>$company,'email'=>$email,'topic'=>$topic,'message'=>$message,'ip'=>evosys_ip(),'user_agent'=>$_SERVER['HTTP_USER_AGENT']??''];$ok=evosys_store(__DIR__.'/../storage/support_requests.csv',array_keys($payload),array_values($payload));$body="New EvoSys Pro support/contact request\n\n";foreach($payload as $k=>$v)$body.=ucwords(str_replace('_',' ',$k)).": ".$v."\n";evosys_notify('EvoSys Pro Website Support — '.($topic?:'General'),$body,$email);evosys_webhook('SUPPORT_WEBHOOK_URL',$payload);if($ok)$success=true;else$errors[]='We could not save your request. Please email support@evosyspro.live.';}}
