<main><section class="page-hero"><div class="wrap"><div class="eyebrow">Support</div><h1>How can we help?</h1><p>Use this form for website, platform, account, onboarding or general questions. Do not send passwords, API keys or other secrets.</p></div></section><section><div class="wrap form-shell"><div class="form-card"><?php if($success||isset($_GET['sent'])):?><div class="success"><strong>Message received.</strong><br>Your request has been recorded.</div><?php else:?><?php if($errors):?><div class="error"><ul><?php foreach($errors as $e):?><li><?=htmlspecialchars($e)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post"><input class="hp" name="website_url" tabindex="-1"><input type="hidden" name="form_started_at" data-started><div class="form-grid"><div class="field"><label>Name *</label><input name="name" required></div><div class="field"><label>Company</label><input name="company"></div><div class="field"><label>Email *</label><input type="email" name="email" required></div><div class="field"><label>Topic</label><select name="topic"><option>General question</option><option>Demo / Sales</option><option>Account / Access</option><option>Customer Launch</option><option>Billing</option><option>Messaging / SMS</option><option>Security</option><option>Other</option></select></div><div class="field full"><label>Message *</label><textarea name="message" required></textarea></div><div class="field full"><button class="btn btn-gold" type="submit">Send Request →</button></div></div></form><?php endif;?></div><aside class="form-side"><div class="card"><div class="eyebrow">Email</div><h3>support@evosyspro.live</h3><p>For general support, privacy, messaging or website questions.</p></div><div class="card"><div class="eyebrow">Sales</div><p>Ready to see the platform? <a href="../request-demo/" style="color:#70e5de">Request a demo.</a></p></div><div class="card"><div class="eyebrow">Client Access</div><p><a href="https://app.evosyspro.live" target="_blank" rel="n